import 'package:flutter/material.dart';
class SaleSummaryCard extends StatelessWidget { const SaleSummaryCard({required this.subtotal, required this.discount, required this.total, super.key}); final double subtotal; final double discount; final double total; @override Widget build(BuildContext context) => Card(child: Padding(padding: const EdgeInsets.all(12), child: Column(children: [Row(children: [const Text('Subtotal'), const Spacer(), Text('\$${subtotal.toStringAsFixed(2)}')]), Row(children: [const Text('Discount'), const Spacer(), Text('\$${discount.toStringAsFixed(2)}')]), const Divider(), Row(children: [const Text('Total', style: TextStyle(fontWeight: FontWeight.bold)), const Spacer(), Text('\$${total.toStringAsFixed(2)}', style: const TextStyle(fontWeight: FontWeight.bold))])]))); }
